-- ===========================================================================
-- Puntos de control - SMETA 6.1 (4 pilares) - resumen divulgativo
-- applicable_scopes contiene el pilar SMETA correspondiente.
-- ===========================================================================

INSERT INTO control_points (chapter_id, ref, title, description, level, guidance, evidence_examples, applicable_scopes, sort_order)
SELECT ch.id, cp.ref, cp.title, cp.description, cp.level, cp.guidance, cp.evidence_examples, cp.scopes, cp.sort_order
FROM audit_standards s
JOIN standard_chapters ch ON ch.standard_id = s.id
JOIN (VALUES
 ('MGMT','0.A','Sistema de gestión y comunicación del código ético','El sitio dispone de procedimientos para implantar el ETI Base Code y la legislación local, con un responsable designado y comunicación a los trabajadores.','MAJOR_MUST','Política ética firmada por la dirección, difundida y comprendida por los trabajadores.','Política ética; organigrama; registros de comunicación','MANAGEMENT',1),
 ('MGMT','0.B','Gestión de proveedores y subcontratistas laborales','Se conocen y evalúan las agencias de empleo y los subcontratistas que aportan mano de obra al sitio.','MAJOR_MUST','Contratos con agencias; verificación de licencias; ausencia de comisiones de contratación cobradas al trabajador.','Contratos con agencias; licencias; política de "empleador paga"','MANAGEMENT',2),
 ('MGMT','0.C','Derecho a trabajar y control de la documentación','Se verifica que todos los trabajadores tienen derecho legal a trabajar y no se retienen sus documentos de identidad originales.','MAJOR_MUST','Copias de permisos de trabajo; los originales quedan en poder del trabajador.','Registro de permisos de trabajo; declaración de no retención de documentos','MANAGEMENT',3),
 ('LABOUR','1.A','Empleo libremente elegido','No hay trabajo forzoso, en régimen de servidumbre, trata ni trabajo penitenciario involuntario; los trabajadores pueden rescindir su contrato con preaviso razonable.','MAJOR_MUST','Convenios OIT nº 29 y 105. Sin depósitos, fianzas ni retención de salarios como coacción.','Entrevistas; contratos; política de movilidad del trabajador','LABOUR',1),
 ('LABOUR','1.B','No al trabajo infantil','No se emplea a menores por debajo de la edad mínima; existe una política de remediación del trabajo infantil.','MAJOR_MUST','Convenios OIT nº 138 y 182. Verificación de edad y expedientes de personal.','Política de trabajo infantil; verificación documental de edad','LABOUR',2),
 ('LABOUR','1.C','Libertad de asociación y negociación colectiva','Se respeta el derecho a constituir sindicatos y a negociar colectivamente; los representantes no sufren discriminación.','MAJOR_MUST','Convenios OIT nº 87 y 98. Donde la ley restringe, se facilitan medios paralelos.','Convenios colectivos; actas de comités de trabajadores','LABOUR',3),
 ('LABOUR','1.D','Salarios dignos y en plazo','Los salarios cumplen como mínimo la ley o el convenio, se pagan puntualmente y las deducciones no disciplinarias están autorizadas.','MAJOR_MUST','Nóminas claras; comparación con el salario mínimo y análisis de brecha con el salario digno.','Nóminas; registros de pago; tablas salariales','LABOUR',4),
 ('LABOUR','1.E','Jornada laboral','Las horas ordinarias y extraordinarias respetan la legislación y los estándares del sector; las horas extra son voluntarias.','MAJOR_MUST','Máximo de referencia de 48 h ordinarias + 12 h extra salvo circunstancias excepcionales; un día libre cada 7.','Registros horarios; recibos de horas extra','LABOUR',5),
 ('LABOUR','1.F','No discriminación','No hay discriminación en contratación, remuneración, acceso a formación, promoción, despido o jubilación.','MAJOR_MUST','Convenios OIT nº 100 y 111. Política y datos desagregados.','Política de igualdad; análisis de plantilla','LABOUR',6),
 ('LABOUR','1.G','Trato regular del empleo','Se cumplen las obligaciones derivadas de la relación laboral y no se elude su protección mediante subcontratación o falsos autónomos.','MAJOR_MUST','Contratos acordes a la actividad real; cotizaciones a la seguridad social.','Contratos; justificantes de cotización','LABOUR',7),
 ('LABOUR','1.H','Trato humano, sin acoso ni abuso','Se prohíben los castigos físicos, la coacción mental o física y el abuso verbal; existe un procedimiento disciplinario justo.','MAJOR_MUST','Procedimiento disciplinario por escrito; registro de sanciones.','Política antiacoso; registros disciplinarios; entrevistas','LABOUR',8),
 ('HS','2.A','Evaluación de riesgos de seguridad y salud','Existe una evaluación de riesgos vigente de todas las actividades y puestos, con medidas de control y un responsable de seguridad.','MAJOR_MUST','Revisar tras accidentes o cambios de proceso.','Evaluación de riesgos; nombramiento del responsable de SST','HEALTH_SAFETY',1),
 ('HS','2.B','Formación en seguridad y simulacros','Los trabajadores reciben formación de seguridad periódica y se realizan simulacros de evacuación registrados.','MAJOR_MUST','Formación en el idioma del trabajador; al menos un simulacro anual.','Registros de formación; informe de simulacro','HEALTH_SAFETY',2),
 ('HS','2.C','Prevención de incendios y vías de evacuación','Salidas señalizadas y despejadas, extintores revisados, alarmas operativas y puntos de encuentro definidos.','MAJOR_MUST','Comprobación visual y registros de mantenimiento.','Certificados de revisión de extintores; plano de evacuación','HEALTH_SAFETY',3),
 ('HS','2.D','Seguridad de máquinas y equipos','Las máquinas disponen de resguardos y parada de emergencia y su mantenimiento está documentado.','MAJOR_MUST','Bloqueo/etiquetado durante el mantenimiento (LOTO).','Registros de mantenimiento; inspección de resguardos','HEALTH_SAFETY',4),
 ('HS','2.E','Sustancias químicas peligrosas','Los productos químicos están etiquetados, con fichas de datos de seguridad accesibles, almacenamiento adecuado y EPI disponible.','MAJOR_MUST','Formación específica; control de derrames; ventilación.','Inventario de químicos; fichas de datos de seguridad; registros de EPI','HEALTH_SAFETY',5),
 ('HS','2.F','Primeros auxilios y vigilancia de la salud','Botiquines suficientes, socorristas formados y, cuando procede, vigilancia de la salud de los trabajadores expuestos.','MAJOR_MUST','Registro de accidentes y enfermedades profesionales.','Certificados de primeros auxilios; libro de accidentes','HEALTH_SAFETY',6),
 ('HS','2.G','Agua potable, saneamiento y comedores','Los trabajadores disponen de agua potable, aseos limpios y suficientes y zonas de descanso/comida higiénicas.','MAJOR_MUST','Ratio de aseos por trabajador conforme a la normativa local.','Inspección de instalaciones','HEALTH_SAFETY',7),
 ('HS','2.H','Alojamiento de los trabajadores','Cuando el empleador facilita alojamiento, este es seguro, limpio, con separación de las zonas de trabajo y servicios básicos.','MAJOR_MUST','Aplicar la guía de alojamiento de trabajadores de SMETA.','Inspección del alojamiento; contratos de alojamiento','HEALTH_SAFETY',8),
 ('ENV','3.A','Permisos y licencias ambientales','El sitio dispone de los permisos ambientales exigidos (vertidos, emisiones, extracción de agua, residuos) y están vigentes.','MAJOR_MUST','Lista de permisos con fechas de caducidad.','Permisos y autorizaciones ambientales','ENVIRONMENT',1),
 ('ENV','3.B','Gestión de residuos y vertidos','Los residuos se segregan, almacenan y entregan a gestores autorizados; las aguas residuales se tratan antes del vertido.','MAJOR_MUST','Registros de retirada de residuos peligrosos y no peligrosos.','Contratos con gestores; analíticas de vertido','ENVIRONMENT',2),
 ('ENV','3.C','Consumo de recursos y energía','Se registran los consumos de agua y energía y existen objetivos de reducción.','RECOMMENDATION','Seguimiento de indicadores y plan de mejora.','Facturas y registros de consumo; plan ambiental','ENVIRONMENT',3),
 ('ENV','3.D','Gestión de productos químicos y suelo','El uso de fertilizantes y fitosanitarios sigue buenas prácticas y se previene la contaminación del suelo y de las aguas subterráneas.','MINOR_MUST','Coherente con la Directiva de Nitratos y el Reg. (CE) 396/2005.','Registros de aplicación; análisis de suelo y agua','ENVIRONMENT',4),
 ('ETHICS','4.A','Política anticorrupción y antisoborno','Existe una política contra el soborno y la corrupción, comunicada y con formación para el personal expuesto.','MAJOR_MUST','Incluye regalos, hospitalidad y pagos de facilitación.','Política anticorrupción; registros de formación','BUSINESS_ETHICS',1),
 ('ETHICS','4.B','Gestión de conflictos de interés y registros','Se declaran los conflictos de interés y se mantienen registros contables y comerciales veraces.','MINOR_MUST','Registro de declaraciones; controles internos.','Registro de conflictos de interés; procedimientos de control interno','BUSINESS_ETHICS',2),
 ('ETHICS','4.C','Canal de denuncias (whistleblowing)','Hay un canal para denunciar conductas poco éticas de forma confidencial y sin represalias, disponible para trabajadores y terceros.','MINOR_MUST','Difusión del canal y protección del denunciante.','Procedimiento de denuncias; registro de casos','BUSINESS_ETHICS',3),
 ('ETHICS','4.D','Conducta ética con la cadena de suministro','Se transmiten los requisitos éticos a proveedores y subcontratistas y se realiza seguimiento.','RECOMMENDATION','Código de conducta de proveedores aceptado.','Código de proveedores firmado; evaluaciones','BUSINESS_ETHICS',4)
) AS cp(chapter_code, ref, title, description, level, guidance, evidence_examples, scopes, sort_order)
  ON cp.chapter_code = ch.code
WHERE s.code = 'SMETA_6_1';
